svg.script:
var stages = [].slice.call(document.querySelectorAll(".panel-stage"));
stages.forEach(function(stage, index) {
  function advance() {
    var next = stages[index + 1];
    if (next && next.classList.contains("panel-stage-hidden")) {
      next.classList.remove("panel-stage-hidden");
      stage.setAttribute("aria-expanded", "true");
      if (next.id === "panel2") next.classList.add("capabilities-revealed");
      if (next.id === "panel3") {
        next.classList.add("user-blocks-revealed");
        if (!window.matchMedia("(prefers-reduced-motion: reduce)").matches) {
          document.querySelector("#cycle-spin").beginElement();
        }
      }
    }
  }
  stage.addEventListener("click", advance);
  stage.addEventListener("keydown", function(event) {
    if (event.key === "Enter" || event.key === " ") {
      event.preventDefault();
      advance();
    }
  });
});
